export type Cell = [number, number];

const key = (x: number, y: number): string => `${x},${y}`;

const neighborsOf = ([x, y]: Cell): Cell[] => [
  [x - 1, y - 1],
  [x, y - 1],
  [x + 1, y - 1],
  [x - 1, y],
  [x + 1, y],
  [x - 1, y + 1],
  [x, y + 1],
  [x + 1, y + 1],
];

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const living = new Set(liveCells.map(([x, y]) => key(x, y)));

  const liveNeighborCount = (cell: Cell): number =>
    neighborsOf(cell).filter(([x, y]) => living.has(key(x, y))).length;

  const candidates = new Map<string, Cell>();
  for (const cell of liveCells) {
    candidates.set(key(cell[0], cell[1]), cell);
    for (const neighbor of neighborsOf(cell)) {
      candidates.set(key(neighbor[0], neighbor[1]), neighbor);
    }
  }

  const survivors: Cell[] = [];
  for (const [cellKey, cell] of candidates) {
    const count = liveNeighborCount(cell);
    const isAlive = living.has(cellKey);
    if (count === 3 || (isAlive && count === 2)) {
      survivors.push(cell);
    }
  }

  return survivors;
}

